const processTemplate = (key: string, code: string, title: string, areaName: string, source: string, sections: DigitalSection[], needsAdaptation = false): DigitalTemplate => ({
    key, code, title, kind: 'process_map', area: areaName, priority: Number(code.split('-').at(-1)), sourceFiles: [source], sourceIsExample: true, needsAdaptation,
    description: `Flujo, responsables, entradas, salidas y seguimiento del proceso de ${title.toLowerCase().replace('mapa de proceso de ', '')}.`,
    sections: [...sections, controlledDocumentFields, approval()],
});

const changeMap = processTemplate('mapa-control-cambios', 'MP-ISO-01', 'Mapa de proceso de control de cambios', 'ISO', 'MP-ISO-XX Control de cambios.vsdx', [
    paragraph('Objetivo y alcance', `Establecer las actividades para implementar los cambios en los procesos de ${company}, mantener íntegro el sistema de gestión de calidad, prevenir ineficiencias y lograr la satisfacción del cliente.`, 'Aplica a cambios significativos internos o externos, planeados o no planeados. Cubre la notificación, análisis de impacto y riesgos, recursos, planeación, ejecución, seguimiento y verificación de eficacia.'),
    paragraph('Responsables e interfaces', 'Coordinación ISO o el responsable del control de cambios recibe la solicitud, coordina el análisis y verifica los registros. El equipo de trabajo ejecuta las acciones. Coordinación ISO comunica los cambios al personal involucrado.', 'Entradas: notificación o solicitud de cambio, requisitos internos, requisitos del cliente, normatividad y decisiones de Dirección. Proveedores del proceso: comunicación interna y externa y revisión por la Dirección. Administración y Finanzas proporciona los recursos necesarios.'),
    paragraph('Flujo y decisiones', '1. Recibir y registrar la notificación o solicitud de cambio en procesos.', '2. Determinar si el cambio es planeado. Si no es planeado, documentar y archivar el registro de cambios no previstos antes de continuar con su análisis.', '3. Coordinar el análisis de impacto y riesgos e integrar el equipo apropiado. Revisar todas las implicaciones del cambio y sus posibles efectos sobre el sistema de gestión.', '4. Determinar si afecta la operación. Cuando la afecte, notificar por los medios institucionales al personal involucrado y al coordinador asignado; obtener los recursos de Administración y Finanzas.', '5. Completar la matriz de control de cambios y, cuando sea necesario, el plan de acción. El equipo ejecuta y da seguimiento a los compromisos.', '6. Coordinar la implementación conforme a la matriz y evaluar su eficacia. Si el cambio no se implementó correctamente, aplicar acciones correctivas mediante ISO-F-08, verificar sus resultados y volver a evaluar.', '7. Comunicar el cambio implementado, conservar la matriz y la evidencia, medir la eficacia del proceso y presentar los resultados en la revisión por la Dirección.'),
    paragraph('Salidas, recursos y medición', 'Salidas: cambio implementado, matriz actualizada, comunicaciones, planes de acción y resultados de eficacia. Destinatarios: procesos afectados, comunicación interna y externa y revisión por la Dirección.', 'Recursos: personal competente, equipo de oficina, acceso al sistema, internet y espacios de reunión. Cada indicador debe definir fórmula, fuente, frecuencia, responsable y meta en su ficha aprobada.'),
    { title: 'Seguimiento de la implementación del proceso', fields: [area('cambios-al-flujo', 'Cambios propuestos al flujo de SMAA'), area('responsables-designados', 'Responsables designados'), area('indicadores', 'Indicadores y metas aprobadas')] },
]);

const communicationMap = processTemplate('mapa-comunicacion', 'MP-ISO-02', 'Mapa de proceso de comunicación interna y externa', 'ISO', 'MP-ISO-XX Comunicación Interna_Externa.vsd', [
    paragraph('Objetivo y alcance', `Asegurar que la documentación e información necesarias para la operación y toma de decisiones de ${company} lleguen de forma eficaz a sus destinatarios.`, 'Aplica a información relevante de clientes, proveedores, autoridades, personal y procesos internos. Comprende definir las fuentes, seleccionar y obtener información, analizarla, comunicarla y conservar sus registros.'),
    paragraph('Responsables y entradas', 'Dirección coordina las comunicaciones relevantes para la alta dirección. Los responsables de procesos mantienen la información actualizada. Los receptores consultan, atienden la urgencia y dan seguimiento. Coordinación ISO mide la eficacia y administra los controles documentales.', 'Entradas: estrategias y requisitos de partes interesadas; información de los procesos; cambios en procesos y normatividad; quejas y satisfacción de clientes; desempeño de proveedores y personal; auditorías internas; documentos controlados. Estas entradas provienen de revisión por Dirección, control de cambios, quejas, medición de satisfacción, compras, Recursos Humanos y control documental.'),
    paragraph('Flujo y decisiones', '1. Dirección define las comunicaciones relevantes, sus fuentes y el tipo de información que debe enviar o recibir respecto de clientes, proveedores, autoridades, personal y procesos internos.', '2. Definir emisores, responsables, receptores primarios y secundarios, frecuencia, urgencia, medios y registros en la matriz de comunicación. Incluir flujos internos, del exterior hacia la empresa y de la empresa hacia el exterior.', '3. Los responsables coordinan el flujo conforme a la matriz. Determinar si la información debe publicarse en la red o sistema de la empresa.', '4. Si requiere publicación en el sistema, colocarla en el espacio apropiado y mantenerla actualizada conforme al proceso y al control documental. Si no requiere publicación, utilizar el canal institucional previsto, por ejemplo correo o documento impreso.', '5. Los receptores consultan o editan según sus permisos; atienden la urgencia fijada por el emisor y dan seguimiento cuando corresponda.', '6. Coordinación ISO mide la eficacia, registra resultados y los presenta en la revisión por la Dirección. Conservar evidencia de entrega, acceso o atención cuando la matriz lo establezca.'),
    paragraph('Salidas y recursos', 'Salidas: información oportuna para las partes interesadas, información disponible en el sistema, comunicaciones registradas y resultados de eficacia. Destinatarios: todos los procesos del sistema de gestión, control documental y revisión por Dirección.', 'Recursos: personal competente, sistema informático, computadora, internet, teléfono, medios impresos y espacio de reunión. Los cambios normativos se comunican únicamente cuando sean pertinentes a las actividades de SMAA.'),
    { title: 'Matriz de comunicación del proceso', table: { key: 'comunicaciones', label: 'Comunicaciones relevantes', minRows: 1, columns: [text('informacion', 'Información', true), text('emisor', 'Emisor o responsable', true), text('receptor', 'Receptores', true), text('frecuencia', 'Frecuencia', true), select('urgencia', 'Urgencia', ['Normal', 'Urgente', 'Inmediata']), text('medio', 'Medio y registro', true), select('direccion', 'Flujo', ['Interno', 'Del exterior al interior', 'Del interior al exterior'], true)] } },
]);

const complaintsMap = processTemplate('mapa-quejas-cliente', 'MP-ISO-03', 'Mapa de proceso de quejas de cliente', 'ISO', 'MP-XXX-XX Mapa de Proceso Quejas de Cliente.vsd', [
    paragraph('Objetivo y alcance', `Atender las inconformidades de los clientes de ${company}, resolver los problemas y prevenir su recurrencia.`, 'Comprende recepción, registro, análisis de causa raíz, correcciones, acciones correctivas, seguimiento, verificación de eficacia y cierre de la queja.'),
    paragraph('Responsables e interfaces', 'Participan quien recibe la queja, el administrador de quejas y el responsable de su análisis. Recursos Humanos asegura personal capacitado. La comunicación interna y externa entrega notificaciones y resultados. Control documental gestiona los documentos que deban modificarse. Dirección revisa el desempeño y los resultados.'),
    paragraph('Flujo y decisiones', '1. Recibir la queja por correo, teléfono, verbalmente o por escrito. Capturar el registro y entregarlo al administrador de quejas con su evidencia.', '2. El administrador revisa la redacción, registra la queja en la base de datos, asigna a quien la analizará y notifica a las gerencias y al cliente cuando corresponda.', '3. Entregar el registro al responsable del análisis por un medio institucional que conserve trazabilidad.', '4. El responsable forma el equipo cuando sea necesario, describe el problema, establece correcciones, analiza la causa raíz, define e implementa acciones correctivas y determina cómo verificará su eficacia.', '5. Completar el reporte de queja con acciones, responsables y fechas y enviarlo al administrador. El administrador monitorea su cumplimiento, actualiza la base de datos y comunica avances al cliente cuando sea necesario.', '6. Verificar la eficacia de las acciones después de su implementación. El periodo de observación y los criterios de eficacia deben estar definidos y aprobados por SMAA antes de iniciar la verificación.', '7. Decidir si las acciones son eficaces. Si no lo son, retomar el análisis y ajustar las acciones; actualizar el reporte y el registro de la queja. Si lo son, entregar evidencia objetiva, conservar los registros y solicitar el cierre al administrador.', '8. Evaluar si deben modificarse documentos o el sistema de gestión. Medir la eficacia del proceso y presentar resultados en la revisión por Dirección.'),
    paragraph('Registros, salidas y recursos', 'Registros: recepción de la queja, base de datos, reporte, análisis de causa y acciones, evidencias de eficacia y cierre. Salidas: queja atendida, reporte actualizado, modificaciones documentales y resultado de medición.', 'Recursos: personal capacitado, sistema de registro, canales de comunicación y acceso a documentos controlados.'),
    { title: 'Definición operativa de SMAA', fields: [{ key: 'dias-verificacion', label: 'Periodo aprobado de verificación en días hábiles', type: 'number', min: 1 }, area('criterios-cierre', 'Criterios y responsables de cierre', true), area('indicadores', 'Indicadores, fuentes y metas aprobadas')] },
], true);

const billingMap = processTemplate('mapa-facturacion-cobranza', 'MP-GAD-01', 'Mapa de proceso de facturación y cobranza', 'Administración y Finanzas', 'MP-XXX-XX Mapa de Proceso de Facturación y  cobranza.vsd', [
    paragraph('Objetivo y alcance', `Definir las actividades para emitir comprobantes fiscales de las ventas de ${company} y dar seguimiento a los saldos pendientes conforme a los acuerdos comerciales.`, 'Incluye recepción de solicitud, recopilación y registro de datos fiscales, emisión y timbrado, envío y archivo de comprobantes, conciliación de pedidos, pagos y facturas, gestión de cobranza y cierre de la cuenta.'),
    paragraph('Responsables e interfaces', 'El responsable de facturación recibe solicitudes y emite comprobantes en la plataforma fiscal autorizada. Administración concilia saldos y acuerdos. Cobranza gestiona atrasos. Comercial valida las condiciones pactadas. Dirección autoriza las decisiones que le competen y revisa los indicadores.'),
    paragraph('Flujo de facturación y decisiones', '1. Recibir y registrar la solicitud de factura y su relación con el pedido o venta.', '2. Consultar si el cliente ya tiene datos fiscales registrados. Si no los tiene, darlos de alta; si ya existen, verificar su vigencia antes de usarlos.', '3. Capturar la solicitud en la plataforma de facturación autorizada. Cuando aplique, enviar prefactura al cliente para su validación.', '4. Emitir y timbrar el comprobante fiscal por el medio autorizado y conservar los archivos PDF y XML. La captura de este mapa en la app no representa por sí sola timbrado fiscal.', '5. Enviar PDF y XML al cliente y al vendedor por el canal institucional. Resguardar los archivos por mes y año fiscal. Cuando proceda, entregar la impresión necesaria para la póliza contable o almacén.'),
    paragraph('Flujo de conciliación y cobranza', '6. Administración revisa diariamente pedidos, pagos y facturas y los concilia contra las condiciones comerciales para identificar atrasos.', '7. ¿Hay atraso? Si no lo hay, mantener el seguimiento. Si existe, contactar al vendedor y a la gerencia comercial para confirmar el adeudo y verificar modificaciones autorizadas a las condiciones; notificar el inicio del protocolo de cobranza aplicable.', '8. Abrir el registro de cobranza del saldo pendiente, emitir la invitación de pago y gestionar un convenio cuando corresponda, conforme a DOC-GAD-02 y las modalidades autorizadas por SMAA.', '9. ¿Se liquidó el saldo? Si se verificó saldo cero, emitir constancia autorizada de liquidación, generar el estado de cuenta en ceros y notificar al cliente. Conservar la evidencia y cerrar la gestión.', '10. Si continúa el adeudo, aplicar el nivel de cobranza correspondiente, elaborar el reporte y enviarlo a Comercial. Reevaluar periódicamente si se liquidó o procede escalar.', '11. ¿Procede una gestión adicional o ejecución? La jefatura de cobranza analiza el expediente y somete la decisión a las autorizaciones aplicables. Si no es viable continuar la gestión ordinaria, preparar el dictamen de cuenta incobrable y solicitar autorización expresa de Dirección. Esta clasificación no condona la obligación.', '12. Conservar invitaciones, convenios, reportes, estados de cuenta, dictámenes y comunicaciones. Medir la eficacia y presentar resultados en la revisión por Dirección.'),
    paragraph('Salidas, recursos e indicadores', 'Salidas: comprobantes PDF y XML, respaldo digital y físico cuando aplique, cuenta conciliada, comunicaciones, convenios, reporte de cobranza, dictamen autorizado cuando corresponda, constancia de liquidación y resultados de eficacia.', 'Recursos: sistema de clientes, plataforma de facturación autorizada, conexión a internet, teléfono y equipo de oficina. Cada indicador debe tener fórmula, fuente, frecuencia, responsable y meta aprobados.'),
    { title: 'Configuración operativa del proceso', fields: [text('plataforma-facturacion', 'Plataforma fiscal autorizada'), area('niveles-cobranza', 'Niveles, plazos y modalidades de cobranza aprobados'), area('autorizaciones', 'Responsables y autorizaciones de SMAA'), area('indicadores', 'Indicadores y metas del proceso')] },
], true);

