type FlowNodeSpec = [id: string, label: string, column: number, row: number, decision?: boolean];
type FlowEdgeSpec = [from: string, to: string, label?: string];
const flowSection = (title: string, specs: FlowNodeSpec[], edges: FlowEdgeSpec[]): DigitalSection => ({
    title,
    flow: {
        width: 1200,
        height: Math.max(...specs.map(node => node[3])) * 160 + 150,
        nodes: specs.map(([id, label, column, row, decision]) => ({ id, label, x: 45 + column * 390, y: 25 + row * 160, width: 330, height: 104, decision })),
        edges: edges.map(([from, to, label]) => ({ from, to, label })),
    },
});

